function clock(seconds) {
    return Math.floor(seconds / 3600) + " h " + String(Math.floor((seconds % 3600) / 60)).padStart(2, "0");
}

function sum(list, measure) {
    return list.reduce((total, entry) => total + measure(entry), 0);
}

/// What stands on a zone's map, most common first. Null when the save has no such zone.
function readObjects(id) {
    let file;
    try {
        file = notes.file("STGDAT" + String(id).padStart(2, "0") + ".BIN");
    } catch (error) {
        return null;
    }
    const header = new DataView(file);
    if (header.getUint32(4, true) !== StageVersion) {
        return { total: 0, kinds: 0, top: [], green: 0, plants: 0, blocks: 0 };
    }
    const view = new DataView(notes.unzip(file, 0x124, header.getUint32(0x10, true)));
    const counts = {};
    let total = 0;
    let green = 0;
    let plants = 0;
    const parts = view.getInt32(PartCount, true);
    for (let i = 0; i < parts; i++) {
        const name = items[partItems[view.getUint32(PartPool + i * 16 + 4, true) & 0xfff]];
        if (name !== undefined && name !== "(Empty)") {
            counts[name] = (counts[name] || 0) + 1;
            total++;
            // Withered plants are their own items, named after the living ones.
            if (Plant.test(name)) {
                plants++;
                green += name.startsWith("Dry ") ? 0 : 1;
            }
        }
    }
    const rows = Object.keys(counts).map((name) => ({ title: name, value: counts[name] }));
    rows.sort((a, b) => b.value - a.value);
    return {
        total: total, kinds: rows.length, top: rows.slice(0, 15), green: green, plants: plants,
        blocks: view.getInt32(BlockCount, true),
    };
}

function read(save) {
    const version = new DataView(save.data).getUint32(4, true);
    if (version !== DataVersion) {
        throw new Error("This module does not know save version 0x" + version.toString(16));
    }
    const end = new DataView(save.data).getUint32(0x10, true);
    const raw = notes.unzip(save.data, 0x130, end);
    const view = new DataView(raw);
    const bytes = new Uint8Array(raw);

    let player = "";
    for (let i = 0; i < 9 && player === ""; i++) {
        player = notes.utf8(raw, PlayerNames + i * 25, 25);
    }

    const met = [];
    for (let i = 0; i < 1050; i++) {
        const base = i * 374;
        if (bytes.subarray(base + 1, base + 17).some((byte) => byte !== 0)) {
            met.push({
                title: villagers[i] || "#" + i,
                value: view.getUint16(base + 0x11, true),
                gift: bytes[base + 0x16] !== 0,
                zone: bytes[Homes + i * 21 + 3],
                thanks: view.getUint16(base + 0x13, true),
                level: bytes[base + 0x15],
                played: view.getFloat32(base + 27, true),
                year: view.getUint16(base + 362, true),
                month: view.getUint16(base + 364, true),
                day: view.getUint16(base + 366, true),
                hour: view.getUint16(base + 368, true),
                minute: view.getUint16(base + 370, true),
            });
        }
    }
    met.sort((a, b) => b.value - a.value);

    const bag = [];
    for (let i = 0; i < 130; i++) {
        const base = Inventory + i * 5;
        const id = view.getUint32(base, true) & 0x1fff;
        if (id !== 0) {
            bag.push({ title: items[id] || "#" + id, value: bytes[base + 4] });
        }
    }

    const moves = [];
    for (let i = 0; i < 64; i++) {
        if (bytes[Abilities + i * 8 + 4] & 1) {
            moves.push({ title: skills[i] || "#" + i, value: view.getUint32(Abilities + i * 8, true) });
        }
    }
    moves.sort((a, b) => b.value - a.value);

    const learned = [];
    const first = Abilities + 64 * 8 + 8;
    for (const id of Object.keys(reactions)) {
        learned.push({ title: reactions[id], check: (bytes[first + Number(id)] & 1) !== 0 });
    }
    const known = learned.filter((row) => row.check).length;

    const collections = Collections.map((collection) => {
        const rows = [];
        for (const id of Object.keys(items)) {
            if (collection.has(Number(id), items[id])) {
                rows.push({ title: items[id], check: bytes[ItemsSeen + Number(id)] !== 0 });
            }
        }
        // Items sharing a name are told apart by their rank.
        const seen = {};
        for (const row of rows) {
            seen[row.title] = (seen[row.title] || 0) + 1;
        }
        const rank = {};
        for (const row of rows) {
            if (seen[row.title] > 1) {
                rank[row.title] = (rank[row.title] || 0) + 1;
                row.title += " " + rank[row.title];
            }
        }
        return { name: collection.name, rows: rows };
    });
    const collectionRows = collections.map((collection) => ({
        title: collection.name,
        done: collection.rows.filter((row) => row.check).length,
        total: collection.rows.length,
    }));

    const learnedMove = (id) => (bytes[Abilities + id * 8 + 4] & 1) !== 0;
    const moveTag = (name) => {
        const id = Teachers[name];
        return id === undefined ? "" : " · " + skills[id] + (learnedMove(id) ? " ✓" : " —");
    };
    const lessons = Object.keys(Teachers).map((name) => ({
        title: name + " · " + skills[Teachers[name]] +
            (met.some((pokemon) => pokemon.title === name) ? "" : " (not met)"),
        check: learnedMove(Teachers[name]),
    }));

    const zones = [];
    for (const id of Object.keys(areas)) {
        const objects = readObjects(Number(id));
        if (objects !== null) {
            zones.push({ id: Number(id), name: areas[id], objects: objects });
        }
    }

    const played = met.reduce((longest, pokemon) => Math.max(longest, pokemon.played), 0);
    const dated = met.filter((pokemon) => pokemon.year > 2000);
    const when = (pokemon) => Months[pokemon.month - 1] + " " + pokemon.day;
    const byPlayTime = met.slice().sort((a, b) => a.played - b.played);
    const days = [];
    for (const pokemon of dated.slice().sort((a, b) => a.played - b.played)) {
        const day = days.find((entry) => entry.title === when(pokemon));
        if (day !== undefined) {
            day.value++;
        } else {
            days.push({ title: when(pokemon), value: 1 });
        }
    }
    const gauge = met.filter((pokemon) => pokemon.thanks > 0).sort((a, b) => b.thanks - a.thanks);
    const objects = sum(zones, (zone) => zone.objects.total);

    // The main tabs keep what reads on its own; numbers that need explaining go to Others.
    const metNames = new Set(met.map((pokemon) => pokemon.title));
    const found = (name) => name === "Ditto" || metNames.has(name) ||
        (OtherNames[name] || []).some((other) => metNames.has(other));
    const missing = Pokedex
        .map((name, index) => ({ title: name, value: "#" + String(index + 1).padStart(3, "0") }))
        .filter((row) => !found(row.title));
    const dexFound = Pokedex.length - missing.length;
    const gifts = met.filter((pokemon) => pokemon.gift);
    const zoneOf = (pokemon) => (zones.find((zone) => zone.id === pokemon.zone) || { name: "" }).name;
    const learnedMoves = [];
    for (const id of Object.keys(skills)) {
        const row = learnedMoves.find((entry) => entry.title === skills[id]);
        if (row !== undefined) {
            row.check = row.check || learnedMove(Number(id));
        } else {
            learnedMoves.push({ title: skills[id], check: learnedMove(Number(id)) });
        }
    }
    const ownedItems = bytes.subarray(ItemsSeen, ItemsSeen + 4608).filter((seen) => seen !== 0).length;

    return {
        title: player,
        keys: [
            { title: "Pokédex", value: dexFound + " / " + Pokedex.length },
            { title: "Gifts", value: gifts.length },
            { title: "Moves", value: lessons.filter((row) => row.check).length },
        ],
        tabs: [
            { name: "Global", views: [{ name: "Global", rows: [
                { title: "Pokédex", done: dexFound, total: Pokedex.length },
                { title: "Gifts waiting", value: gifts.length },
                { title: "Moves from Pokémon", done: lessons.filter((row) => row.check).length, total: lessons.length },
                { title: "Reactions learned", done: known, total: learned.length },
            ].concat(collectionRows, [
                { title: "Zones opened", value: zones.length },
            ]) }] },
            { name: "Zones", views: zones.map((zone) => {
                const living = met.filter((pokemon) => pokemon.zone === zone.id);
                return {
                    name: zone.name,
                    rows: [
                        { title: "Pokémon living here", value: living.length },
                        { title: "Gifts waiting", value: living.filter((pokemon) => pokemon.gift).length },
                    ].concat(living.map((pokemon) => ({
                        title: pokemon.title + moveTag(pokemon.title) + (pokemon.gift ? " (gift)" : ""),
                        value: "",
                    }))),
                };
            }).concat([{ name: "Not met yet (any zone)", rows: missing }]) },
            { name: "Collections", views: [{ name: "All collections", rows: collectionRows }].concat(collections) },
            { name: "Bag", views: [{ name: "Bag", rows: bag }] },
            { name: "Abilities", views: [
                { name: "Moves", rows: learnedMoves },
                { name: "Reactions", rows: learned },
            ] },
            { name: "Others", views: [
                { name: "Totals", rows: [
                    { title: "Play time, at least (newest Pokémon met)", value: clock(played) },
                    { title: "Items in the bag", value: sum(bag, (item) => item.value) },
                    { title: "Items ever owned", value: ownedItems },
                    { title: "Times moves were used", value: sum(moves, (move) => move.value) },
                    { title: "Objects on the maps", value: objects },
                ] },
                { name: "Friendship points (raw)", rows: met.map((pokemon) => ({
                    title: pokemon.title, value: pokemon.value,
                })) },
                { name: "Gift levels reached", rows: met.slice()
                    .sort((a, b) => b.level - a.level)
                    .map((pokemon) => ({ title: pokemon.title, value: pokemon.level })) },
                { name: "Thank gauge (full = next gift)", rows: gauge.map((pokemon) => ({
                    title: pokemon.title, done: pokemon.thanks, total: 100,
                })) },
                { name: "Times each move was used", rows: moves },
            ].concat(zones.map((zone) => ({
                name: "Map of " + zone.name,
                rows: [
                    { title: "Living plants (not withered)", done: zone.objects.green, total: zone.objects.plants },
                    { title: "Objects placed", value: zone.objects.total },
                    { title: "Kinds of objects", value: zone.objects.kinds },
                ].concat(zone.objects.top),
            }))) },
        ],
    };
}
